#include <bits/stdc++.h>
using namespace std;

constexpr int INF = 0x3f3f3f3f;

struct Edge {
    int dest;
    int reverse;
    int capacity;
    int weight;
};

vector<vector<Edge>> adj;
vector<int> seen, ptr, d, pot;
int total_nodes;

int new_node() {
    adj.emplace_back();
    return total_nodes++;
}

void connect(int u, int v, int cap, int cost) {
    adj[u].push_back({v, (int)adj[v].size(), cap, cost});
    adj[v].push_back({u, (int)adj[u].size() - 1, 0, -cost});
}

bool shortest_path(int src, int dst) {
    fill(d.begin(), d.end(), INF);
    fill(seen.begin(), seen.end(), 0);
    using pii = pair<int, int>;
    priority_queue<pii, vector<pii>, greater<pii>> heap;
    heap.emplace(d[src] = 0, src);
    while (!heap.empty()) {
        auto [du, u] = heap.top(); heap.pop();
        if (seen[u]) continue;
        seen[u] = true;
        for (auto& e : adj[u]) {
            int v = e.dest;
            int dv = du + pot[u] + e.weight - pot[v];
            if (e.capacity == 0 || seen[v] || d[v] <= dv) continue;
            heap.emplace(d[v] = dv, v);
        }
    }
    return seen[dst];
}

bool bfs_layered(int src, int dst) {
    fill(seen.begin(), seen.end(), 0);
    queue<int> q;
    q.push(src);
    seen[src] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (auto& e : adj[u]) {
            int v = e.dest;
            if (seen[v] || e.capacity == 0) continue;
            if (d[v] != d[u] + e.weight - pot[v] + pot[u]) continue;
            seen[v] = seen[u] + 1;
            q.push(v);
        }
    }
    return seen[dst];
}

int dfs_flow(int u, int dst, int flow) {
    if (u == dst) return flow;
    int pushed = 0;
    for (int& i = ptr[u]; i < (int)adj[u].size(); ++i) {
        auto& e = adj[u][i];
        int v = e.dest;
        if (e.capacity == 0 || seen[v] != seen[u] + 1) continue;
        if (d[v] != d[u] + e.weight - pot[v] + pot[u]) continue;
        int df = dfs_flow(v, dst, min(e.capacity, flow));
        pushed += df;
        flow -= df;
        e.capacity -= df;
        adj[v][e.reverse].capacity += df;
        if (flow == 0) break;
    }
    return pushed;
}

pair<int, int> solve(int src, int dst, int limit) {
    int total_flow = 0, total_cost = 0;
    fill(pot.begin(), pot.end(), 0);
    while (shortest_path(src, dst)) {
        int flow = 0;
        while (bfs_layered(src, dst)) {
            fill(ptr.begin(), ptr.end(), 0);
            int df = dfs_flow(src, dst, limit);
            limit -= df;
            flow += df;
            if (limit == 0) break;
        }
        total_flow += flow;
        total_cost += (d[dst] + pot[dst]) * flow;
        for (int i = 0; i < total_nodes; ++i)
            pot[i] += d[i];
        if (limit == 0) break;
    }
    return {total_flow, total_cost};
}

int main() {
    int n, m, k, c, d;
    scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);
    int layers = max(n, k) * 2;
    new_node();
    int source = new_node();
    int sink = new_node();
    for (int j = 0; j < k; ++j) {
        int a;
        scanf("%d", &a);
        --a;
        connect(source, a, 1, 0);
    }
    for (int z = 1; z <= m; ++z) {
        int u, v;
        scanf("%d %d", &u, &v);
        --u; --v;
        for (int i = 0; i + 1 < layers; ++i) {
            int u1 = u + i * n, v1 = v + (i + 1) * n;
            int u2 = u + (i + 1) * n, v2 = v + i * n;
            for (int j = 0; j < k; ++j) {
                connect(u1, v1, 1, c + d * (2 * j + 1));
                connect(v2, u2, 1, c + d * (2 * j + 1));
            }
        }
    }
    for (int i = 0; i + 1 < layers; ++i) {
        for (int j = 0; j < n; ++j) {
            int u = j + i * n, v = j + (i + 1) * n;
            connect(u, v, INF, c);
        }
    }
    for (int i = 0; i < layers; ++i)
        connect(i * n, sink, INF, 0);
    printf("%d\n", solve(source, sink, INF).second);
    return 0;
}
